notes.text:
.button {
  background: #4338ff;
  transform: translateY(0);
  transition: background 0.2s ease, transform 0.2s ease;
}

.button:hover {
  background: #2f25d6;
  transform: translateY(-2px);
}

.panel {
  transition: transform 0.35s cubic-bezier(0.33, 1, 0.68, 1);
}

@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.card {
  animation: fade-up 0.5s ease-out both;
}

.card {
  animation: fade-up 0.5s ease-out both;
  animation-delay: calc(var(--i) * 60ms);
}

.ball {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: gold;
  animation: bounce 0.8s cubic-bezier(0.33, 1, 0.68, 1) infinite alternate;
}

.shadow {
  width: 64px;
  height: 10px;
  border-radius: 50%;
  background: #000;
  animation: squash 0.8s cubic-bezier(0.33, 1, 0.68, 1) infinite alternate;
}

@keyframes bounce {
  to { transform: translateY(-120px); }
}

@keyframes squash {
  from { transform: scaleX(1); opacity: 0.55; }
  to   { transform: scaleX(0.4); opacity: 0.12; }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
